   257  bool zmq::zmtp_engine_t::handshake_v1_0_unversioned ()
   258  {
   259      //  We send and receive rest of routing id message
   260      if (session ()->zap_enabled ()) {
   261          // reject ZMTP 1.0 connections if ZAP is enabled
   262          error (protocol_error);
   263          return false;
   264      }
   265
   266      _encoder = new (std::nothrow) v1_encoder_t (_options.out_batch_size);
   267      alloc_assert (_encoder);
   268
   269      _decoder = new (std::nothrow)
   270        v1_decoder_t (_options.in_batch_size, _options.maxmsgsize);
   271      alloc_assert (_decoder);
   272
   273      //  We have already sent the message header.
   274      //  Since there is no way to tell the encoder to
   275      //  skip the message header, we simply throw that
   276      //  header data away.
   277      const size_t header_size =
   278        _options.routing_id_size + 1 >= UCHAR_MAX ? 10 : 2;
   279      unsigned char tmp[10], *bufferp = tmp;
   280
   281      //  Prepare the routing id message and load it into encoder.
   282      //  Then consume bytes we have already sent to the peer.
   283      int rc = _routing_id_msg.close ();
   284      zmq_assert (rc == 0);
   285      rc = _routing_id_msg.init_size (_options.routing_id_size);
   286      zmq_assert (rc == 0);
   287      memcpy (_routing_id_msg.data (), _options.routing_id,
   288              _options.routing_id_size);
   289      _encoder->load_msg (&_routing_id_msg);
   290      const size_t buffer_size = _encoder->encode (&bufferp, header_size);
   291      zmq_assert (buffer_size == header_size);
   292
   293      //  Make sure the decoder sees the data we have already received.
   294      _inpos = _greeting_recv;
   295      _insize = _greeting_bytes_read;
   296
   297      //  To allow for interoperability with peers that do not forward
   298      //  their subscriptions, we inject a phantom subscription message
   299      //  message into the incoming message stream.
   300      if (_options.type == ZMQ_PUB || _options.type == ZMQ_XPUB)
   301          _subscription_required = true;
   302
   303      //  We are sending our routing id now and the next message
   304      //  will come from the socket.
   305      _next_msg = &zmtp_engine_t::pull_msg_from_session;
   306
   307      //  We are expecting routing id message.
   308      _process_msg = static_cast<int (stream_engine_base_t::*) (msg_t *)> (
   309        &zmtp_engine_t::process_routing_id_msg);
   310
   311      return true;
   312  }
